function calcularViralidad(m) {
  return (
    (m.likes || 0) * 1.2 +
    (m.retweets || 0) * 3 +
    (m.replies || 0) * 2 +
    (m.quotes || 0) * 2.5 +
    (m.views || 0) * 0.002
  );
}

