const items = $input.all();
const results = [];

function findHTML(obj) {
    if (!obj || typeof obj !== "object") return null;

    for (const key of Object.keys(obj)) {
        if (typeof obj[key] === "string" && obj[key].includes("<") && obj[key].includes(">")) {
            return obj[key];
        }
    }
    return null;
}

function getDomain(u) {
    try {
        return new URL(u).hostname.replace(/^www\./, "");
    } catch {
        return "";
    }
}

for (let i = 0; i < items.length; i++) {
    const item = items[i];

    // 🔗 URL de origen POR ITEM (no global)
    let sourceUrl = "";

    // 1. Desde el propio item
    sourceUrl = item.json?.link || item.json?.enlace || "";

    // 2. Fallback al nodo previo (si existe y corresponde a este item)
    if (!sourceUrl) {
        try {
            sourceUrl = $('Code in JavaScript14')?.all()?.[i]?.json?.link || "";
        } catch {
            sourceUrl = "";
        }
    }

    const sourceDomain = getDomain(sourceUrl);

    // 1. Hallar HTML
    const html = findHTML(item.json);
    if (!html) {
        results.push({
            json: {
                url: sourceUrl || "",
                titulo: "",
                contenido_limpio: ""
            }
        });
        continue;
    }

    // 2. LIMPIEZA inicial
    let clean = html
        .replace(/<script[\s\S]*?<\/script>/gi, "")
        .replace(/<style[\s\S]*?<\/style>/gi, "");

    clean = clean
        .replace(/(\+?\d{1,3}[\s.-]?)?(\(?\d{2,4}\)?[\s.-]?)?\d{3,4}[\s.-]?\d{4}/g, "")
        .replace(/copyright\s*©?\s*2025/gi, "")
        .replace(/©\s*2025/gi, "")
        .replace(/suscribite|suscríbete|registrate|regístrate|seguinos|seguir leyendo|leer más|publicidad|anuncio|newsletter|aceptar cookies|cookies|ver más/gi, "");

    // 3. RESOLVER URL FINAL (por item)
    let url = sourceUrl;

    // canonical
    if (!url) {
        const canonical = clean.match(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']+)["']/i);
        if (canonical) {
            const d = getDomain(canonical[1]);
            if (!sourceDomain || d === sourceDomain) {
                url = canonical[1];
            }
        }
    }

    // og:url
    if (!url) {
        const og = clean.match(/<meta[^>]+property=["']og:url["'][^>]+content=["']([^"']+)["']/i);
        if (og) {
            const d = getDomain(og[1]);
            if (!sourceDomain || d === sourceDomain) {
                url = og[1];
            }
        }
    }

    // 4. EXTRAER TÍTULO
    let titulo = "";

    let m1 = clean.match(/<meta[^>]+name=["']title["'][^>]+content=["']([^"']+)["']/i);
    if (m1) titulo = m1[1].trim();

    if (!titulo) {
        let m2 = clean.match(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i);
        if (m2) titulo = m2[1].trim();
    }

    if (!titulo) {
        let m3 = clean.match(/<title>(.*?)<\/title>/i);
        if (m3) titulo = m3[1].trim();
    }

    titulo = item.json?.title || item.json?.titulo || titulo;

    // 5. EXTRAER PÁRRAFOS
    const paragraphs = clean.match(/<p[^>]*>(.*?)<\/p>/gi) || [];
    const bigBlocks = paragraphs
        .map(p => p.replace(/<\/?[^>]+>/g, "").trim())
        .filter(t => t.length > 0)
        .join("\n\n");

    // 6. PUSH FINAL
    results.push({
        json: {
            url,
            titulo,
            contenido_limpio: bigBlocks
        }
    });
}

return results;

