    Boolean(videoHD) ||                     // 🔥 link en videosHD[0]
    (Array.isArray(images) && images.length > 0) ||
    Boolean(transcripcion);

  if (tieneMultimedia) {
    score += 2;
  }

  // 🔹 Devolvemos TODO igual + score_narrativo
  return {
    json: {
      ...input,
      score_narrativo: Number(score.toFixed(2))
    }
  };
});

